import React from 'react';
import './App.css';

const products = [
  {
    id: 1,
    name: "Gucci",
    price: 1099,
    status: "Almost Out Of Stock",
    image: "https://via.placeholder.com/150",
  },
  {
    id: 2,
    name: "U.S.Polo",
    price: 2000,
    status: "Stock is Available",
    image: "https://via.placeholder.com/150",
  },
  {
    id: 3,
    name: "Wrogn",
    price: 5099,
    status: "Almost Out Of Stock",
    image: "https://via.placeholder.com/150",
  },
  {
    id: 4,
    name: "Allen Solly",
    price: 1099,
    status: "Out Of Stock",
    image: "https://via.placeholder.com/150",
  }
];

function getStatusColor(status) {
  if (status === "Stock is Available") return "green";
  if (status === "Out Of Stock") return "red";
  return "orange";
}

function App() {

  const handleClick = (product) => {
    if (product.status === "Out Of Stock") {
      ;
    } else {
      
    }
  };

  return (
    <div className="container">
      <h2 className="title">React List Rendering</h2>
      <div className="card-container">
        {products.map(product => (
          <div className="card" key={product.id}>
            <img src={product.image} alt={product.name} />
            <h3>{product.name}</h3>
            <p>₹ {product.price}.00</p>
            <p style={{ color: getStatusColor(product.status) }}>{product.status}</p>
            <button 
              onClick={() => handleClick(product)} 
              className="buy-btn"
              disabled={product.status === "Out Of Stock"}
            >
              {product.status === "Out Of Stock" ? "Unavailable" : "Buy Now"}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
